// Python-flavored value semantics for JSON data.
//
// The bundled jsonschema version distinguishes booleans from numbers
// strictly (True != 1), while integers and floats compare by value
// (1 == 1.0). Objects compare key-order-insensitively, arrays
// element-by-element. These helpers mirror that behavior.

export function isPlainObject(value) {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

export function hasKey(obj, key) {
  return Object.prototype.hasOwnProperty.call(obj, key);
}

// JSON Schema draft-07 type check (jsonschema TypeChecker semantics).
export function isType(instance, type) {
  switch (type) {
    case "null":
      return instance === null;
    case "boolean":
      return typeof instance === "boolean";
    case "string":
      return typeof instance === "string";
    case "array":
      return Array.isArray(instance);
    case "object":
      return isPlainObject(instance);
    case "number":
      return typeof instance === "number";
    case "integer":
      // Python ints, and floats with an integral value, are integers.
      return typeof instance === "number" && Number.isInteger(instance);
    default:
      return false;
  }
}

function tagOf(value) {
  if (value === null) return "null";
  if (Array.isArray(value)) return "array";
  const t = typeof value;
  if (t === "boolean") return "boolean";
  if (t === "string") return "string";
  if (t === "number") return "number";
  if (t === "object") return "object";
  return "unknown";
}

// Deep equality with the observed jsonschema semantics:
// bool is never equal to number, int equals float by value,
// objects compare without regard to key order.
export function pyEq(a, b) {
  const ta = tagOf(a);
  const tb = tagOf(b);
  if (ta !== tb) return false;
  switch (ta) {
    case "null":
      return true;
    case "boolean":
    case "string":
    case "number":
      return a === b; // NaN !== NaN, as in Python
    case "array":
      if (a.length !== b.length) return false;
      for (let i = 0; i < a.length; i++) {
        if (!pyEq(a[i], b[i])) return false;
      }
      return true;
    case "object": {
      const ka = Object.keys(a);
      const kb = Object.keys(b);
      if (ka.length !== kb.length) return false;
      for (const k of ka) {
        if (!hasKey(b, k) || !pyEq(a[k], b[k])) return false;
      }
      return true;
    }
    default:
      return false;
  }
}

// Python len(str) counts Unicode code points, not UTF-16 units.
export function strLen(s) {
  let n = 0;
  for (const _ of s) n++;
  return n;
}

