// Error types mirroring jsonschema.exceptions behavior.

// A single validation error. `validator` is the keyword that produced it
// (or null for a `false` boolean schema), `path` is the instance path.
export function makeError(validator, path, message) {
  return { validator, path: path.slice(), message };
}

// Raised by check_schema when a schema fails the meta-schema,
// mirroring jsonschema.exceptions.SchemaError (which aborts the
// Python program with exit code 1 before anything is printed).
export class SchemaError extends Error {
  constructor(message) {
    super(message);
    this.name = "SchemaError";
  }
}

