// JSON parsing compatible with Python's json.loads.
//
// json.loads accepts the bare constants NaN, Infinity and -Infinity,
// which JSON.parse rejects. We rewrite them (outside of string literals)
// to sentinel strings, parse, then convert the sentinels back to the
// corresponding JS number values.

const NAN_SENTINEL = "PyJsOn::NaN::7f3a91c2";
const INF_SENTINEL = "PyJsOn::Infinity::7f3a91c2";
const NINF_SENTINEL = "PyJsOn::-Infinity::7f3a91c2";

function isWordChar(ch) {
  return ch !== undefined && /[A-Za-z0-9_]/.test(ch);
}

function preprocess(text) {
  let out = "";
  let inString = false;
  let escaped = false;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (inString) {
      out += ch;
      if (escaped) escaped = false;
      else if (ch === "\\") escaped = true;
      else if (ch === '"') inString = false;
      continue;
    }
    if (ch === '"') {
      inString = true;
      out += ch;
      continue;
    }
    if (text.startsWith("Infinity", i) && !isWordChar(text[i + 8])) {
      // A leading '-' is emitted immediately before (no whitespace is
      // allowed between '-' and 'Infinity' by json.loads).
      if (out.endsWith("-")) {
        out = out.slice(0, -1) + JSON.stringify(NINF_SENTINEL);
      } else {
        out += JSON.stringify(INF_SENTINEL);
      }
      i += 7;
      continue;
    }
    if (text.startsWith("NaN", i) && !isWordChar(text[i + 3])) {
      out += JSON.stringify(NAN_SENTINEL);
      i += 2;
      continue;
    }
    out += ch;
  }
  return out;
}

function convert(value) {
  if (typeof value === "string") {
    if (value === NAN_SENTINEL) return NaN;
    if (value === INF_SENTINEL) return Infinity;
    if (value === NINF_SENTINEL) return -Infinity;
    return value;
  }
  if (Array.isArray(value)) {
    for (let i = 0; i < value.length; i++) value[i] = convert(value[i]);
    return value;
  }
  if (value !== null && typeof value === "object") {
    for (const key of Object.keys(value)) value[key] = convert(value[key]);
    return value;
  }
  return value;
}

export function pyJsonParse(text) {
  return convert(JSON.parse(preprocess(text)));
}

