// Draft7Validator: error iteration, validity checks, schema checks and
// local $ref resolution, mirroring the observed jsonschema behavior.

import { KEYWORD_VALIDATORS } from "./keywords.mjs";
import { makeError, SchemaError } from "./errors.mjs";
import { isPlainObject, hasKey } from "./pytypes.mjs";
import { META_SCHEMA } from "./metaSchema.mjs";

export class Draft7Validator {
  constructor(schema) {
    this.schema = schema;
    this._ctx = {
      descend: (instance, subschema, path) => this.iterErrors(instance, subschema, path),
      isValid: (instance, subschema) => this._isValidAgainst(instance, subschema),
    };
  }

  *iterErrors(instance, schema = this.schema, path = []) {
    if (schema === true) {
      return;
    }
    if (schema === false) {
      yield makeError(null, path, `False schema does not allow ${JSON.stringify(instance)}`);
      return;
    }
    if (!isPlainObject(schema)) {
      // jsonschema crashes on non-object, non-boolean schemas.
      throw new TypeError("schema must be an object or a boolean");
    }
    if (hasKey(schema, "$ref")) {
      // In draft-07, $ref replaces all sibling keywords.
      const resolved = this._resolve(schema.$ref);
      yield* this.iterErrors(instance, resolved, path);
      return;
    }
    for (const [keyword, value] of Object.entries(schema)) {
      const fn = KEYWORD_VALIDATORS[keyword];
      if (fn !== undefined) {
        yield* fn(this._ctx, value, instance, schema, path);
      }
      // Unknown keywords are silently ignored.
    }
  }

  _isValidAgainst(instance, schema) {
    for (const _error of this.iterErrors(instance, schema, [])) {
      return false;
    }
    return true;
  }

  isValid(instance) {
    return this._isValidAgainst(instance, this.schema);
  }

  // Resolve a local reference ("#", "#/definitions/foo", ...) against
  // the root schema document, with JSON Pointer unescaping.
  _resolve(ref) {
    if (typeof ref !== "string" || !ref.startsWith("#")) {
      throw new Error(`Unresolvable reference: ${JSON.stringify(ref)}`);
    }
    if (ref === "#") {
      return this.schema;
    }
    const pointer = ref.slice(1);
    if (!pointer.startsWith("/")) {
      throw new Error(`Unresolvable reference: ${JSON.stringify(ref)}`);
    }
    let node = this.schema;
    for (const rawPart of pointer.slice(1).split("/")) {
      const part = decodeURIComponent(rawPart)
        .replace(/~1/g, "/")
        .replace(/~0/g, "~");
      if (Array.isArray(node)) {
        const index = Number(part);
        if (!Number.isInteger(index) || index < 0 || index >= node.length) {
          throw new Error(`Unresolvable reference: ${JSON.stringify(ref)}`);
        }
        node = node[index];
      } else if (node !== null && typeof node === "object" && hasKey(node, part)) {
        node = node[part];
      } else {
        throw new Error(`Unresolvable reference: ${JSON.stringify(ref)}`);
      }
    }
    return node;
  }

  // Mirrors jsonschema's check_schema: validates the schema against the
  // draft-07 meta-schema and raises SchemaError on the first problem.
  // Returns null (Python's None) when the schema is valid.
  checkSchema(schema) {
    const metaValidator = new Draft7Validator(META_SCHEMA);
    for (const error of metaValidator.iterErrors(schema)) {
      throw new SchemaError(
        `The schema is invalid under the draft-07 meta-schema (${error.message})`,
      );
    }
    return null;
  }
}

