// Mirrors Python argparse: usage/errors go to stderr with exit code 2,
// --help prints to stdout with exit code 0.

function usageLine(prog) {
  return `usage: ${prog} [-h] --a A --b B`;
}

function fail(prog, message) {
  process.stderr.write(`${usageLine(prog)}\n`);
  process.stderr.write(`${prog}: error: ${message}\n`);
  process.exit(2);
}

function printHelp(prog) {
  process.stdout.write(`${usageLine(prog)}\n`);
  process.stdout.write(`\n`);
  process.stdout.write(`options:\n`);
  process.stdout.write(`  -h, --help  show this help message and exit\n`);
  process.stdout.write(`  --a A       instance (JSON string)\n`);
  process.stdout.write(`  --b B       schema (JSON string)\n`);
  process.exit(0);
}

// argparse treats a token as an option string if it starts with '-' and
// is not a negative number (no defined options look like negative numbers).
function looksLikeOption(token) {
  if (!token.startsWith("-")) return false;
  if (/^-\d+$|^-\d*\.\d+$/.test(token)) return false;
  return token.length > 1;
}

const OPTION_NAMES = new Set(["--a", "--b"]);

export function parseArgs(argv, prog) {
  const values = {};
  const seen = new Set();
  const extras = [];

  for (let i = 0; i < argv.length; i++) {
    const token = argv[i];
    if (token === "-h" || token === "--help") {
      printHelp(prog);
    }
    let name = token;
    let inlineValue;
    const eq = token.indexOf("=");
    if (token.startsWith("--") && eq !== -1) {
      name = token.slice(0, eq);
      inlineValue = token.slice(eq + 1);
    }
    if (OPTION_NAMES.has(name)) {
      seen.add(name);
      if (inlineValue !== undefined) {
        values[name] = inlineValue;
      } else if (i + 1 < argv.length && !looksLikeOption(argv[i + 1])) {
        values[name] = argv[++i];
      } else {
        fail(prog, `argument ${name}: expected one argument`);
      }
    } else {
      extras.push(token);
    }
  }

  const missing = ["--a", "--b"].filter((name) => !seen.has(name));
  if (missing.length > 0) {
    fail(prog, `the following arguments are required: ${missing.join(", ")}`);
  }
  if (extras.length > 0) {
    fail(prog, `unrecognized arguments: ${extras.join(" ")}`);
  }

  return { a: values["--a"], b: values["--b"] };
}

