// Node.js (ESM) port of /workspace/dataset/jsonschema/test18.py.
//
// Mirrors the Python program: parses --a (instance JSON) and --b (schema
// JSON), runs a Draft-07 validator over them, and prints error counts,
// validity checks, schema check results and error-tree totals.

import { basename } from "node:path";
import { parseArgs } from "./lib/argparse.mjs";
import { pyJsonParse } from "./lib/pyjson.mjs";
import { Draft7Validator } from "./lib/validator.mjs";
import { ErrorTree } from "./lib/errorTree.mjs";

function pyBool(value) {
  return value ? "True" : "False";
}

function pyNone(value) {
  return value === null ? "None" : String(value);
}

function main() {
  const prog = basename(process.argv[1] || "test18.mjs");
  const args = parseArgs(process.argv.slice(2), prog);

  // json.loads failures abort the Python program with a traceback (exit 1).
  const instance = pyJsonParse(args.a);
  const schema = pyJsonParse(args.b);

  const validator = new Draft7Validator(schema);

  // Build error tree
  const errors = [...validator.iterErrors(instance)];
  const tree = new ErrorTree(errors);

  // Navigate tree
  const total = tree.totalErrors;

  // Iterate multiple times
  const firstPass = [...validator.iterErrors(instance)];
  const secondPass = [...validator.iterErrors(instance)];

  // Check instance multiple times with different approaches
  const check1 = validator.isValid(instance);
  const check2 = validator.isValid(instance);
  const check3 = validator.isValid(instance);

  // Validate schema multiple times (raises SchemaError on invalid schemas)
  const schemaCheck1 = validator.checkSchema(schema);
  const schemaCheck2 = validator.checkSchema(schema);

  // Create error trees for each pass
  const tree1 = new ErrorTree(firstPass);
  const tree2 = new ErrorTree(secondPass);

  console.log(total);
  console.log(firstPass.length);
  console.log(secondPass.length);
  console.log(pyBool(check1));
  console.log(pyBool(check2));
  console.log(pyBool(check3));
  console.log(pyNone(schemaCheck1));
  console.log(pyNone(schemaCheck2));
  console.log(tree1.totalErrors);
  console.log(tree2.totalErrors);
}

try {
  main();
} catch (error) {
  // Any unhandled failure (bad JSON, invalid schema, resolution errors)
  // corresponds to a Python traceback: nothing on stdout, exit code 1.
  process.stderr.write(`${error && error.stack ? error.stack : error}\n`);
  process.exit(1);
}

